export const RES_FACTOR = { "1080p": 0.75, "1440p": 0.9, "4K": 1 };
export const WORKLOAD_FACTOR = {
  story: 0.7,
  online: 1,
  stream: 1.15
};
export const BASE_FPS = { "1080p": 130, "1440p": 100, "4K": 65 };
export const WORKLOAD_META = {
  story: { label: "Modo historia", hint: "Un jugador, sin streaming" },
  online: { label: "GTA Online", hint: "Sala de 30 jugadores, física intensa" },
  stream: { label: "Streaming + grabación", hint: "OBS x264 + captura de juego" }
};
export function computeBalance(gpu, cpu, res, mode) {
  const gpuDemand = 100 * RES_FACTOR[res];
  const cpuDemand = 100 * WORKLOAD_FACTOR[mode];
  const headGpu = gpu.score / gpuDemand;
  const headCpu = cpu.score / cpuDemand;
  const delta = headGpu - headCpu;
  const absPct = Math.round(Math.abs(delta) * 100);
  let verdict;
  if (delta > 0.07)
    verdict = "cpu";
  else if (delta < -0.07)
    verdict = "gpu";
  else
    verdict = "balanced";
  const limiting = Math.min(headGpu, headCpu);
  const fpsLow = Math.round(limiting * BASE_FPS[res] * 0.8);
  const fpsHigh = Math.round(limiting * BASE_FPS[res] * 1.15);
  const avgFps = Math.round(limiting * BASE_FPS[res]);
  return { verdict, absPct, headGpu, headCpu, fpsLow, fpsHigh, avgFps };
}
export function suggestUpgrade(gpu, cpu, res, mode) {
  const { verdict, absPct } = computeBalance(gpu, cpu, res, mode);
  if (verdict === "balanced")
    return null;
  const list = verdict === "cpu" ? CPUS : GPUS;
  const current = verdict === "cpu" ? cpu : gpu;
  const candidates = [...list].sort((a, b) => a.score - b.score).filter((p) => p.score > current.score);
  for (const cand of candidates) {
    const test = verdict === "cpu" ? computeBalance(gpu, cand, res, mode) : computeBalance(cand, cpu, res, mode);
    if (test.verdict === "balanced") {
      return { part: cand, kind: verdict, fromPct: absPct, toPct: test.absPct };
    }
  }
  const top = candidates[candidates.length - 1];
  if (!top)
    return null;
  const test = verdict === "cpu" ? computeBalance(gpu, top, res, mode) : computeBalance(top, cpu, res, mode);
  return { part: top, kind: verdict, fromPct: absPct, toPct: test.absPct };
}
export function verdictLabelOf(r) {
  return r.verdict === "balanced" ? "Configuración equilibrada" : r.verdict === "cpu" ? `Cuello de botella de CPU ${r.absPct} %` : `Cuello de botella de GPU ${r.absPct} %`;
}
